        ?string $token = null,
    ): RequestInterface;

    public function delete(
        string $section,
        string $resource,
        string $id,
        string $authorizationHeader,
        ?string $token = null,
    ): RequestInterface;

    public function upload(
        string $section,
        string $resource,
        array $files,
        string $authorizationHeader,
        ?string $token = null,
    ): RequestInterface;

    public function transition(
        string $section,
        string $resource,
        string $id,
        string $transition,
    ): RequestInterface;

    public function customItemAction(
        string $section,
        string $resource,
        string $id,
        string $type,
        string $action,
    ): RequestInterface;

    public function custom(
        string $url,
        string $method,
        array $additionalHeaders = [],
        ?string $token = null,
    ): RequestInterface;

    public function default(
        string $section,
        string $url,
        string $method,
        array $queryParameters = [],
        array $additionalHeaders = [],
        ?string $token = null,
    ): RequestInterface;
}
